using System.Collections.Generic;
using System.Linq;
using UnityEngine;

namespace Astrea.RunModifiers;

[CreateAssetMenu(fileName = "ScorchedBattlefieldRunModifier", menuName = "Data/RunModifiers/ScorchedBattlefieldRunModifier", order = 0)]
public class ScorchedBattlefieldRunModifier : RunModifier
{
	public override void Initialize()
	{
		ReferenceSingleton<RunModifiersManager>.Instance.ScorchedBattlefieldRunModifier = this;
	}

	public Reward[] GetBattleModifiedRewards(Reward[] nonModifiedRewards)
	{
		List<Reward> list = nonModifiedRewards.DuplicateAsList();
		int num = list.Count((Reward item) => item is DiceReward);
		if (num == 0)
		{
			return nonModifiedRewards;
		}
		int num2 = list.FindIndex((Reward item) => item is DiceReward);
		if (num == 2)
		{
			list.RemoveAt(num2 + 1);
			list.RemoveAt(num2);
		}
		else
		{
			list.RemoveAt(num2);
		}
		return list.ToArray();
	}
}
